/**
 * IDEAS-B1-05 /brain routes for the studio server (read-only GETs).
 *  /brain                 page   /brain.js  client
 *  /brain/graph?src=memory|celegans|hemibrain|flywire   nodes+edges with 3D positions
 *  /brain/learn?n=4       next Hebbian learning step on the memory graph (fired edges)
 * Memory file: TESSERA_BRAIN_MEMORY (path) or docs/v2/v2-memory.jsonl. Not a TESSERA_ENABLE flag.
 */
import { readFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { buildBrain, createBrainLoop, layout3d } from "./view.mjs";
import { TEMPLATES, loadTemplate } from "./templates.mjs";
const HERE = dirname(fileURLToPath(import.meta.url));
const memPath = () => process.env.TESSERA_BRAIN_MEMORY || join(HERE, "../../../../docs/v2/v2-memory.jsonl");
const cache = new Map(); let loop = null;
function memory() { return existsSync(memPath()) ? readFileSync(memPath(), "utf8") : ""; }
export function brainGraph(src = "memory", { layout = true } = {}) {
  const ck = layout ? src : `${src}:nolayout`;
  if (cache.has(ck)) return cache.get(ck);
  let out;
  if (src === "memory") {
    const b = buildBrain(memory());
    out = { src, nodes: b.nodes.map((n) => ({ id: n.id, group: n.type, p: n.p })), edges: [...b.relations.map(([a, c, w]) => ({ a, b: c, w, kind: "relation" })), ...b.synapses.map(([a, c, w]) => ({ a, b: c, w, kind: "synapse" }))], modules: b.modules, license: "Tessera memory graph" };
  } else if (TEMPLATES[src]) {
    const t = loadTemplate(src); const ids = [...new Set(t.edges.flatMap((e) => [e.from, e.to]))];
    const max = Math.max(...t.edges.map((e) => e.syn));
    const layer = (id) => (id.startsWith("in") ? -1 : id.startsWith("out") ? 1 : 0);
    const grid = (id) => { const n = Number(id.replace(/\D/g, "")); const w = id.startsWith("mlp") ? 16 : 10; return [((n % w) - w / 2) * 1.6, (Math.floor(n / w) - w / 2) * 1.6]; };
    const pos = t.kind === "weights" ? ids.map((id) => [layer(id) * 22, ...grid(id)]) : t.coords && ids.every((id) => t.coords[id]) ? ids.map((id) => t.coords[id]) : !layout ? ids.map(() => [0, 0, 0]) : layout3d(ids, t.edges.map((e) => [e.from, e.to, 4 * Math.log1p(e.syn) / Math.log1p(max)]), { iters: 100 });
    out = { src, name: t.name, nodes: ids.map((id, i) => ({ id, group: t.cortex?.[id] ?? t.networks?.[id] ?? id.replace(/[_(].*$/, "").replace(/[LR]$/, "").replace(/\d+$/, ""), p: pos[i] })), edges: t.edges.map((e) => ({ a: e.from, b: e.to, w: Math.log1p(e.syn), syn: e.syn, sign: e.inh > e.exc ? -1 : e.exc > 0 ? 1 : 0, kind: "synapse" })), license: `${t.species} · ${t.name} · ${t.license}${t.coordsSource ? ` · positions: ${t.coordsSource}` : " · positions: force layout"}` };
  } else return null;
  cache.set(ck, out); return out;
}
export function handleBrain(req, res, url) {
  if (req.method !== "GET") return false;
  const send = (type, body, code = 200) => { res.writeHead(code, { "content-type": type }); res.end(body); return true; };
  if (url.pathname === "/brain") return send("text/html; charset=utf-8", PAGE);
  if (url.pathname === "/brain.js") return send("text/javascript; charset=utf-8", readFileSync(join(HERE, "brain-client.js")));
  if (url.pathname === "/brain/graph") { const g = brainGraph(url.searchParams.get("src") ?? "memory"); return g ? send("application/json", JSON.stringify(g)) : send("application/json", '{"error":"unknown src"}', 404); }
  if (url.pathname === "/brain/learn") { loop ??= createBrainLoop(memory()); const s = loop.step(Math.min(16, Number(url.searchParams.get("n")) || 1)); if (s.done) loop = null; return send("application/json", JSON.stringify(s)); }
  return false;
}
const PAGE = `<!doctype html><meta charset="utf-8"><title>Tessera brain</title>
<style>body{margin:0;background:#05060a;color:#cfd6e6;font:13px system-ui}#ui{position:fixed;top:10px;left:10px;z-index:2}#info{position:fixed;bottom:10px;left:10px;max-width:70vw;opacity:.8}canvas{display:block}</style>
<div id="ui"><label>Brain <select id="src"><option value="memory">Tessera memory + synapses</option>${Object.keys(TEMPLATES).map((k) => `<option value="${k}">${k} — ${TEMPLATES[k].species}</option>`).join("")}</select></label> <span id="stat"></span></div>
<div id="info"></div><canvas id="brain-3d"></canvas>
<script type="module" src="/brain.js"></script>`;

/**
 * IDEAS-B1-05 Brain view model. Real memory graph + synapse layer -> 3D force layout and a
 * learning-event stream for the studio /brain page. No synthetic nodes: every node is a
 * memory entity or relation endpoint, every edge a recorded relation or learned synapse.
 */
import { loadGraph, hebbian, coMentionEpisodes, synapse } from "./synapse.mjs";
import { connectome } from "./synapse.mjs";
const K = (a, b) => (a < b ? `${a}\u0000${b}` : `${b}\u0000${a}`);
function rng(seed = 7) { let x = seed >>> 0; return () => ((x = (x * 1664525 + 1013904223) >>> 0) / 2 ** 32); }
/** Deterministic 3D force layout (repulsion via grid buckets + spring edges + centering). */
export function layout3d(ids, links, { iters = 120, seed = 7 } = {}) {
  const r = rng(seed); const n = ids.length; const idx = new Map(ids.map((id, i) => [id, i]));
  const P = ids.map(() => [r() * 20 - 10, r() * 20 - 10, r() * 20 - 10]);
  const L = links.map(([a, b, w]) => [idx.get(a), idx.get(b), w]).filter(([a, b]) => a != null && b != null);
  for (let t = 0; t < iters; t++) {
    const F = P.map(() => [0, 0, 0]); const cool = 1 - t / iters;
    const cell = 4; const grid = new Map();
    P.forEach((p, i) => { const k = p.map((v) => Math.floor(v / cell)).join(","); (grid.get(k) ?? grid.set(k, []).get(k)).push(i); });
    P.forEach((p, i) => {
      const c = p.map((v) => Math.floor(v / cell));
      for (let dx = -1; dx <= 1; dx++) for (let dy = -1; dy <= 1; dy++) for (let dz = -1; dz <= 1; dz++) {
        for (const j of grid.get(`${c[0] + dx},${c[1] + dy},${c[2] + dz}`) ?? []) {
          if (j <= i) continue; const d = [0, 1, 2].map((q) => p[q] - P[j][q]); const d2 = d[0] ** 2 + d[1] ** 2 + d[2] ** 2 + 0.01;
          const f = 2 / d2; for (let q = 0; q < 3; q++) { F[i][q] += d[q] * f; F[j][q] -= d[q] * f; }
        }
      }
    });
    for (const [a, b, w] of L) { const d = [0, 1, 2].map((q) => P[b][q] - P[a][q]); const len = Math.hypot(...d) || 1; const f = 0.05 * Math.min(w, 4) * (len - 2) / len; for (let q = 0; q < 3; q++) { F[a][q] += d[q] * f; F[b][q] -= d[q] * f; } }
    P.forEach((p, i) => { for (let q = 0; q < 3; q++) p[q] += Math.max(-1, Math.min(1, (F[i][q] - p[q] * 0.01) * cool)); });
  }
  return P.map((p) => p.map((v) => Math.round(v * 100) / 100));
}
/** Build the view: nodes (type, module), relation edges, top synapse edges by weight. */
export function buildBrain(jsonl, { maxSynapses = 2500, layoutIters = 120 } = {}) {
  const g = loadGraph(jsonl);
  const episodes = coMentionEpisodes(g);
  const learned = loadGraph(jsonl); for (const e of episodes) hebbian(learned, e);
  const syn = [...learned.syn].sort((a, b) => b[1] - a[1]).slice(0, maxSynapses).map(([k, w]) => [...k.split("\u0000"), Math.round(w * 1000) / 1000]);
  const rel = [...g.edges].map(([k, w]) => [...k.split("\u0000"), w]);
  const ids = [...g.nodes.keys()];
  const pos = layout3d(ids, [...rel, ...syn], { iters: layoutIters });
  const c = connectome(learned);
  const nodes = ids.map((id, i) => ({ id, type: g.nodes.get(id).type, module: c.label.get(id), p: pos[i] }));
  return { nodes, relations: rel, synapses: syn, episodes, hubs: c.hubs, modules: c.modules };
}
/** Live learning: replay real co-activation episodes as Hebbian updates; each step returns fired edges with new weights. */
export function createBrainLoop(jsonl) {
  const g = loadGraph(jsonl); const eps = coMentionEpisodes(g); let i = 0;
  return {
    episodes: eps.length,
    step(n = 1) {
      const fired = [];
      for (let s = 0; s < n && i < eps.length; s++, i++) {
        const e = eps[i]; hebbian(g, e);
        for (const m of e.slice(1)) fired.push([e[0], m, Math.round(synapse(g, e[0], m) * 1000) / 1000]);
      }
      return { done: i >= eps.length, at: i, fired };
    },
  };
}
export { K as synKey };

/**
 * IDEAS-B1-01 brain/synapse layer. Weighted memory graph over MCP-memory JSONL
 * (entities + relations), Hebbian strengthening on co-activation, exponential decay,
 * spreading-activation recall, and a connectome-style module/hub map (label propagation).
 * Pure functions; no network, no I/O except what the caller passes in.
 */
export function loadGraph(jsonl) {
  const nodes = new Map(); const edges = new Map();
  for (const line of String(jsonl).split("\n")) {
    if (!line.trim()) continue; let r; try { r = JSON.parse(line); } catch { continue; }
    if (r.type === "entity") nodes.set(r.name, { type: r.entityType, obs: r.observations?.length ?? 0, text: `${r.name} ${(r.observations ?? []).join(" ")}`.toLowerCase() });
    else if (r.type === "relation" && r.from && r.to) {
      for (const n of [r.from, r.to]) if (!nodes.has(n)) nodes.set(n, { type: "unknown", obs: 0, text: n.toLowerCase() });
      link(edges, r.from, r.to, 1);
    }
  }
  return { nodes, edges, syn: new Map() };
}
const key = (a, b) => (a < b ? `${a}\u0000${b}` : `${b}\u0000${a}`);
function link(edges, a, b, w) { if (a === b) return; const k = key(a, b); edges.set(k, (edges.get(k) ?? 0) + w); }
export const weight = (g, a, b) => g.edges.get(key(a, b)) ?? 0;
export const synapse = (g, a, b) => g.syn.get(key(a, b)) ?? 0;
export function neighbors(g, n) {
  const out = [];
  for (const [k, w] of g.edges) { const [a, b] = k.split("\u0000"); if (a === n) out.push([b, w]); else if (b === n) out.push([a, w]); }
  return out;
}
/** Hebbian: every pair active together gains rate*(1-w/cap) on its synapse (kept apart from
 * the structural relation edges so recorded facts are never overwritten). */
export function hebbian(g, active, { rate = 0.5, cap = 10 } = {}) {
  const a = [...new Set(active)];
  for (let i = 0; i < a.length; i++) for (let j = i + 1; j < a.length; j++) {
    if (a[i] === a[j]) continue; const w = synapse(g, a[i], a[j]); g.syn.set(key(a[i], a[j]), w + rate * (1 - w / cap));
  }
  return g;
}
/** Co-activation episodes: each entity fires with every other entity its observations mention. */
export function coMentionEpisodes(g, { minLen = 4 } = {}) {
  const names = [...g.nodes.keys()].filter((n) => n.length >= minLen);
  const eps = [];
  for (const [n, v] of g.nodes) { const hit = names.filter((m) => m !== n && v.text?.includes(m.toLowerCase())); if (hit.length) eps.push([n, ...hit]); }
  return eps;
}
/** Decay all synapses by factor; prune below floor (synaptic pruning). Returns pruned count. */
export function decay(g, { factor = 0.9, floor = 0.05 } = {}) {
  let pruned = 0;
  for (const [k, w] of g.syn) { const nw = w * factor; if (nw < floor) { g.syn.delete(k); pruned++; } else g.syn.set(k, nw); }
  return pruned;
}
const toks = (s) => new Set(String(s ?? "").split(/[^a-z0-9]+/).filter((w) => w.length > 3));
/** Link recall: rank non-neighbours of seed by Adamic-Adar over relations + synapse strength
 * + observation-token overlap. Returns top-k names. Use with no synapses for the baseline. */
export function predict(g, seed, k = 5, { synW = 2, textW = 1 } = {}) {
  const adj = adjacency(g); const nb = new Map(adj.get(seed) ?? []); const deg = (n) => (adj.get(n) ?? []).length;
  const T = toks(g.nodes.get(seed)?.text); const out = [];
  for (const n of g.nodes.keys()) {
    if (n === seed || nb.has(n)) continue;
    let s = 0; for (const [m] of adj.get(n) ?? []) if (nb.has(m)) s += 1 / Math.log(1 + deg(m));
    s += synW * synapse(g, seed, n);
    if (textW) { const U = toks(g.nodes.get(n)?.text); let i = 0; for (const w of T) if (U.has(w)) i++; s += textW * (i / ((T.size + U.size - i) || 1)); }
    if (s > 0) out.push([n, s]);
  }
  return out.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, k).map(([n]) => n);
}
/** Spreading activation from seed, 2 hops, top-k (excluding seed). */
export function recall(g, seed, k = 5, { hops = 2, damp = 0.5 } = {}) {
  const adj = adjacency(g); const act = new Map([[seed, 1]]); let front = new Map([[seed, 1]]);
  for (let h = 0; h < hops; h++) {
    const next = new Map();
    for (const [n, a] of front) {
      const nb = adj.get(n) ?? []; const tot = nb.reduce((s, [, w]) => s + w, 0) || 1;
      for (const [m, w] of nb) { const v = a * damp * (w / tot) * nb.length ** 0; next.set(m, (next.get(m) ?? 0) + v); }
    }
    for (const [n, v] of next) act.set(n, (act.get(n) ?? 0) + v); front = next;
  }
  act.delete(seed);
  return [...act].sort((x, y) => y[1] - x[1] || (x[0] < y[0] ? -1 : 1)).slice(0, k).map(([n]) => n);
}
function adjacency(g) {
  const adj = new Map(); const push = (a, b, w) => { if (!adj.has(a)) adj.set(a, []); adj.get(a).push([b, w]); };
  for (const [k, w] of g.edges) { const [a, b] = k.split("\u0000"); push(a, b, w); push(b, a, w); }
  return adj;
}
/** Connectome map: weighted label propagation modules + hubs (top weighted degree). */
export function connectome(g, { iters = 10, hubs = 5 } = {}) {
  const adj = adjacency(g); const label = new Map([...g.nodes.keys()].map((n) => [n, n]));
  const order = [...g.nodes.keys()].sort();
  for (let t = 0; t < iters; t++) {
    let changed = 0;
    for (const n of order) {
      const score = new Map();
      for (const [m, w] of adj.get(n) ?? []) score.set(label.get(m), (score.get(label.get(m)) ?? 0) + w);
      if (!score.size) continue;
      const best = [...score].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1))[0][0];
      if (best !== label.get(n)) { label.set(n, best); changed++; }
    }
    if (!changed) break;
  }
  const deg = order.map((n) => [n, (adj.get(n) ?? []).reduce((s, [, w]) => s + w, 0)]).sort((a, b) => b[1] - a[1]);
  return { modules: new Set(label.values()).size, label, hubs: deg.slice(0, hubs).map(([n]) => n) };
}

