}
export function benchLearn() {
  const topics = ["git", "tests", "gates", "relay", "tokens", "mesh"]; const difficulty = { git: 0.3, tests: 0.5, gates: 0.9, relay: 0.6, tokens: 0.4, mesh: 0.8 };
