    const [, ms] = time(() => {
      const T2 = createTimeline();
      lines.forEach((line, t) => {
        if (!line.trim()) return;
        let r; try { r = JSON.parse(line); } catch { return; }
        if (r.type === "entity" && r.name) T2.addNode(t, r.name, { type: r.entityType });
