  }
}
console.log({ rebuildP50: pct(lat2,0.5), rebuildP95: pct(lat2,0.95), rebuildMax: pct(lat2,1) });

// diff cost
const [, dms] = time(() => T.diff(index[0], index[index.length-1]));
const d = T.diff(index[Math.floor(index.length*0.25)], index[Math.floor(index.length*0.75)]);
