const after = samples.map(([t,p]) => time(() => replayAt(jsonl, t, p))[1]);
console.log({ beforeP50: pct(before,.5), beforeP95: pct(before,.95), afterP50: pct(after,.5), afterP95: pct(after,.95), samples: samples.length });
EOF

